defmodule Crosswake.TestSupport.VersionStampTest do
  use ExUnit.Case, async: true

  alias Crosswake.TestSupport.VersionStamp

  @xml_11 "<!-- Generated by crosswake 0.2.11 (template_version: 4) -->"
  @xml_12 "<!-- Generated by crosswake 0.2.12 (template_version: 4) -->"

  describe "normalize_stamp/1" do
    test "a version-only stamp change normalizes equal" do
      assert VersionStamp.normalize_stamp(@xml_11) == VersionStamp.normalize_stamp(@xml_12)

      assert VersionStamp.normalize_stamp(@xml_11) ==
               "<!-- Generated by crosswake <CROSSWAKE_VERSION> (template_version: 4) -->"
    end

    test "pre-release and build-metadata versions normalize like a plain version" do
      assert VersionStamp.normalize_stamp(
               "// Generated by crosswake 0.3.0-rc.1 (template_version: 4)"
             ) ==
               "// Generated by crosswake <CROSSWAKE_VERSION> (template_version: 4)"

      assert VersionStamp.normalize_stamp(
               "# Generated by crosswake 1.2.3+build.5 (template_version: 4)"
             ) ==
               "# Generated by crosswake <CROSSWAKE_VERSION> (template_version: 4)"

      assert VersionStamp.normalize_stamp("# Generated by crosswake 1.2.3-rc.1+build.5 (x)") ==
               "# Generated by crosswake <CROSSWAKE_VERSION> (x)"
    end

    test "a changed template_version still differs" do
      other = String.replace(@xml_12, "template_version: 4", "template_version: 5")
      refute VersionStamp.normalize_stamp(@xml_11) == VersionStamp.normalize_stamp(other)
    end

    test "a one-byte change outside the stamp still differs" do
      a = @xml_11 <> "\n<plist version=\"1.0\">"
      b = @xml_12 <> "\n<plist version=\"1.1\">"
      refute VersionStamp.normalize_stamp(a) == VersionStamp.normalize_stamp(b)
    end

    test "a missing stamp still differs from a stamped file" do
      refute VersionStamp.normalize_stamp(@xml_11) == VersionStamp.normalize_stamp("")
    end

    test "a stamp-free binary-safe string is returned byte-identical" do
      bytes = <<0, 255, 1, 2, "no stamp here", 200>>
      assert VersionStamp.normalize_stamp(bytes) == bytes
    end

    test "a file with two stamps normalizes both" do
      two = @xml_11 <> "\n" <> @xml_11

      assert VersionStamp.normalize_stamp(two) ==
               VersionStamp.normalize_stamp(@xml_12 <> "\n" <> @xml_12)

      refute VersionStamp.normalize_stamp(two) =~ "0.2.11"
    end
  end

  describe "stamp_count/1" do
    test "counts stamps" do
      assert VersionStamp.stamp_count("") == 0
      assert VersionStamp.stamp_count(@xml_11) == 1
      assert VersionStamp.stamp_count(@xml_11 <> "\n" <> @xml_12) == 2
    end
  end

  describe "normalize_crosswake_version/1" do
    test "a version-only JSON change normalizes equal" do
      assert VersionStamp.normalize_crosswake_version(~s({"crosswake_version": "0.2.11"})) ==
               VersionStamp.normalize_crosswake_version(~s({"crosswake_version": "0.2.12"}))

      assert VersionStamp.normalize_crosswake_version(~s({"crosswake_version":"0.3.0-rc.1"})) ==
               VersionStamp.normalize_crosswake_version(~s({"crosswake_version":"0.2.12"}))
    end

    test "any other JSON value still differs" do
      refute VersionStamp.normalize_crosswake_version(~s({"crosswake_version": "0.2.11", "x": 1})) ==
               VersionStamp.normalize_crosswake_version(
                 ~s({"crosswake_version": "0.2.11", "x": 2})
               )
    end

    test "committed seam fixture carries exactly two crosswake_version values" do
      fixture =
        Path.expand(
          "../../../packages/crosswake-shell-core-ios/Tests/CrosswakeShellCoreTests/Resources/host_command_seam_fixture.json",
          __DIR__
        )

      assert VersionStamp.crosswake_version_count(File.read!(fixture)) == 2
    end
  end
end
